flow.typescript:
// D8 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_flow.ts
//   병목(Decoder) 찾기 → 양자화로 줄이기 → VAD 로 안 듣기 → LocalAgreement 로 말하는 도중에 확정하기, 네 가지 핵심 계산을 한 파일에서 맛보기
// 대체 경로: faster-whisper · whisper.cpp 모델은 쓰지 않고, 비용 모델과 장난감 배열·합성 신호로 같은 계산을 한다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 5;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

// 1) 병목: Encoder 는 한 번, Decoder 는 토큰마다 -> 토큰이 많을수록 Decoder 몫이 커진다 (비용 단위 = 임의 단위)
const ENC_COST = 100;
const DEC_COST_PER_TOKEN = 8;
for (const n of [5, 20, 40]) {
  const total = ENC_COST + DEC_COST_PER_TOKEN * n;
  console.log(`토큰 ${n}개: 전체 ${total.toFixed(1)} = Encoder ${ENC_COST} + Decoder ${total - ENC_COST} (Decoder 몫 ${Math.round(((total - ENC_COST) / total) * 100)}%)`);
}
check((DEC_COST_PER_TOKEN * 40) / (ENC_COST + DEC_COST_PER_TOKEN * 40) > 0.5, "토큰이 40개쯤 되면 Decoder 가 절반 넘게 차지해요.");

// 2) 양자화: float32 -> int8 (눈금 간격 scale = 최대값 / 127)
const w = Float32Array.from({ length: 256 * 128 }, () => 0.05 * randn());
const scale = Math.max(...w.map(Math.abs)) / 127;
const q = Int8Array.from(w, (v) => Math.max(-127, Math.min(127, Math.round(v / scale))));
let errSum = 0;
let magSum = 0;
w.forEach((v, i) => {
  errSum += Math.abs(v - q[i] * scale);
  magSum += Math.abs(v);
});
const err = errSum / magSum;
console.log(`메모리 ${w.byteLength / 1024} KB -> ${q.byteLength / 1024} KB, 평균 상대 오차 ${(err * 100).toFixed(1)}%`);
check(w.byteLength === 4 * q.byteLength && err < 0.03, "int8 은 float32 의 1/4 크기이고 오차는 몇 % 이내예요.");

// 3) VAD: 소리 크기로 말 구간만 남기면 Whisper 에 넣을 길이가 줄어든다
const y = Float32Array.from({ length: 12 * SR }, (_, i) => {
  const t = i / SR;
  return (t % 4 < 1.5 ? 0.3 * Math.sin(2 * Math.PI * 200 * t) : 0) + 0.001 * randn(); // 4초마다 1.5초만 말
});
const frame = 400;
let on = 0;
const nFrames = Math.floor(y.length / frame);
for (let i = 0; i < nFrames; i++) {
  let s = 0;
  for (let j = 0; j < frame; j++) s += y[i * frame + j] ** 2;
  if (Math.sqrt(s / frame) > 0.02) on++;
}
const ratio = on / nFrames;
console.log(`전체 ${y.length / SR}초 중 말 ${(ratio * (y.length / SR)).toFixed(1)}초만 Whisper 에 넣음 (${Math.round(ratio * 100)}%)`);
check(ratio > 0.3 && ratio < 0.45, "말 구간은 약 37% 예요 (1.5초 / 4초).");

// 4) LocalAgreement: 두 번 연속 같은 앞부분만 확정
const lcp = (a: string[], b: string[]): number => {
  let i = 0;
  while (i < Math.min(a.length, b.length) && a[i] === b[i]) i++;
  return i;
};
const h1 = ["아이구루", "교육"];
const h2 = ["아이구루", "교육센터에서", "라이"];
console.log("공통 앞부분 단어 수:", lcp(h1, h2), "->", h2.slice(0, lcp(h1, h2)).join(" "), "만 확정");
check(lcp(h1, h2) === 1 && lcp(["가", "나"], ["다", "나"]) === 0, "앞에서부터 같은 단어가 몇 개 이어지는지가 확정 길이예요.");

bottleneck.typescript:
// D8 · Part 1 · 왜 느린가: 시간이 어디로 가는지 재기 (Encoder 와 Decoder) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_bottleneck.ts
//   Encoder 는 한 번, Decoder 는 토큰 하나마다 한 번 돈다: 장난감 트랜스포머 블록의 곱셈 횟수를 세어 Decoder 몫이 토큰 수에 따라 커지는 것을 확인하고 실제 시간도 함께 찍는다
// 대체 경로: whisper-small 을 돌려 시간을 재는 대신, 같은 구조의 작은 행렬 곱 반복(장난감)으로 곱셈 횟수와 시간을 잰다. 시간은 컴퓨터마다 달라 정답 판정에는 곱셈 횟수만 쓴다.
const D = 64; // 모델 차원
const FRAMES = 300; // Encoder 칸 수 (Whisper 는 1500칸, 여기서는 시간 절약용으로 줄임)
const LAYERS = 4;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 3;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const rnd = (s: number): number => (uni() - 0.5) * s;
const W = Array.from({ length: D }, () => Float64Array.from({ length: D }, () => rnd(0.2)));
const mults = { enc: 0, dec: 0 };

const matvec = (v: Float64Array): Float64Array => {
  const out = new Float64Array(D);
  for (let i = 0; i < D; i++) {
    let s = 0;
    for (let j = 0; j < D; j++) s += v[j] * W[j][i];
    out[i] = Math.tanh(s);
  }
  return out;
};

function encoder(x: Float64Array[]): Float64Array[] {
  let cur = x;
  for (let l = 0; l < LAYERS; l++) {
    cur = cur.map(matvec);
    mults.enc += cur.length * D * D;
  }
  return cur;
}

function decoderStep(hEnc: Float64Array[], tokVec: Float64Array): Float64Array {
  let v = tokVec;
  for (let l = 0; l < LAYERS; l++) {
    v = matvec(v);
    mults.dec += D * D;
    const scores = hEnc.map((f) => f.reduce((s, a, i) => s + a * v[i], 0)); // cross-attention: 프레임과 내적
    mults.dec += FRAMES * D;
    const m = Math.max(...scores);
    const e = scores.map((s) => Math.exp(s - m));
    const sum = e.reduce((a, b) => a + b, 0);
    const ctx = new Float64Array(D);
    e.forEach((w, t) => {
      for (let i = 0; i < D; i++) ctx[i] += (w / sum) * hEnc[t][i];
    });
    mults.dec += FRAMES * D;
    v = v.map((a, i) => a + 0.01 * ctx[i]);
  }
  return v;
}

const xAudio = Array.from({ length: FRAMES }, () => Float64Array.from({ length: D }, () => rnd(2)));
let t0 = performance.now();
const h = encoder(xAudio);
const encTime = performance.now() - t0; // Encoder 는 한 번만
const nTok = 30;
let tok = Float64Array.from({ length: D }, () => rnd(2));
t0 = performance.now();
for (let i = 0; i < nTok; i++) tok = decoderStep(h, tok); // 토큰 하나마다 Decoder 를 한 번씩
const decTime = performance.now() - t0;
const total = encTime + decTime; // 전체 = Encoder + Decoder (빈칸: total - encTime = decTime)
console.log(`시간: 전체 ${total.toFixed(0)} ms = Encoder ${encTime.toFixed(0)} ms + Decoder ${decTime.toFixed(0)} ms (토큰 ${nTok}개)`);
console.log(`곱셈 횟수: Encoder ${mults.enc.toLocaleString()} | Decoder ${mults.dec.toLocaleString()} (${Math.round((mults.dec / (mults.enc + mults.dec)) * 100)}%)`);

// 토큰 수에 따른 Decoder 몫: 곱셈 횟수 모델
const encM = LAYERS * FRAMES * D * D;
const decM = (n: number): number => n * LAYERS * (D * D + 2 * FRAMES * D);
for (const n of [5, 30, 100]) console.log(`  토큰 ${n}개 -> Decoder 몫 ${Math.round((decM(n) / (encM + decM(n))) * 100)}%`);
check(mults.enc === encM && mults.dec === decM(nTok), "곱셈 횟수는 식과 같아야 해요.");
check(decM(100) / (encM + decM(100)) > decM(5) / (encM + decM(5)), "토큰이 많을수록 Decoder 가 차지하는 몫이 커져요.");

engine.typescript:
// D8 · Part 2 · faster-whisper: 같은 모델, 더 빠른 엔진 (KV 캐시 · 게으른 생성기) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_engine.ts
//   엔진이 빠른 이유 하나: 이미 계산한 key·value 를 저장(KV 캐시)해 두면 토큰이 늘어도 한 걸음 일이 늘지 않는다. 캐시 있음·없음의 곱셈 횟수와 결과가 같음을 확인하고, 제너레이터(function*)가 '꺼낼 때' 계산하는 것도 확인
// 대체 경로: faster-whisper(CTranslate2) 와 small 모델 대신, 한 층짜리 장난감 self-attention 디코더로 캐시 유무를 비교한다.
const D = 16;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 11;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const mat = (r: number, c: number, s: number): number[][] => Array.from({ length: r }, () => Array.from({ length: c }, () => (uni() - 0.5) * s));
const Wq = mat(D, D, 0.6);
const Wk = mat(D, D, 0.6);
const Wv = mat(D, D, 0.6);
const embed = mat(50, D, 2);
const proj = (x: number[], W: number[][]): number[] => W[0].map((_, j) => x.reduce((s, v, i) => s + v * W[i][j], 0));
const dot = (a: number[], b: number[]): number => a.reduce((s, v, i) => s + v * b[i], 0);
const softmax = (s: number[]): number[] => {
  const m = Math.max(...s);
  const e = s.map((v) => Math.exp(v - m));
  const t = e.reduce((a, b) => a + b, 0);
  return e.map((v) => v / t);
};
const attend = (Ks: number[][], Vs: number[][], q: number[]): number[] => {
  const w = softmax(Ks.map((k) => dot(k, q) / Math.sqrt(D)));
  return Vs[0].map((_, j) => w.reduce((s, a, t) => s + a * Vs[t][j], 0));
};
const nextTok = (out: number[]): number => embed.map((e) => dot(e, out)).reduce((b, v, i, a) => (v > a[b] ? i : b), 0);

function decodeNoCache(first: number, steps: number): [number[], number] {
  const toks = [first];
  let mults = 0;
  for (let s = 0; s < steps; s++) {
    const X = toks.map((t) => embed[t]); // 지금까지 모든 토큰을 매번 다시 투영
    const Ks = X.map((x) => proj(x, Wk));
    const Vs = X.map((x) => proj(x, Wv));
    mults += 2 * toks.length * D * D;
    const q = proj(X[X.length - 1], Wq);
    const out = attend(Ks, Vs, q);
    mults += D * D + 2 * toks.length * D;
    toks.push(nextTok(out));
  }
  return [toks, mults];
}

function decodeCache(first: number, steps: number): [number[], number] {
  const toks = [first];
  let mults = 0;
  const Ks: number[][] = []; // KV 캐시: 한 번 계산한 key · value 를 쌓아 둠
  const Vs: number[][] = [];
  for (let s = 0; s < steps; s++) {
    const x = embed[toks[toks.length - 1]]; // 새 토큰 하나만 투영
    Ks.push(proj(x, Wk));
    Vs.push(proj(x, Wv));
    mults += 2 * D * D;
    const q = proj(x, Wq);
    const out = attend(Ks, Vs, q);
    mults += D * D + 2 * toks.length * D;
    toks.push(nextTok(out));
  }
  return [toks, mults];
}

const [a, ma] = decodeNoCache(3, 30);
const [b, mb] = decodeCache(3, 30);
console.log(`캐시 없음 곱셈 ${ma.toLocaleString()}번 | 캐시 있음 ${mb.toLocaleString()}번 -> ${(ma / mb).toFixed(1)}배 적음`);
console.log("생성한 토큰 앞 10개:", a.slice(0, 10).join(", "));
check(a.join() === b.join() && mb < ma, "캐시를 써도 결과 토큰은 똑같고, 곱셈은 줄어야 해요.");

// 게으른 생성기: 호출만으로는 일하지 않고, 꺼낼 때(Array.from) 일한다
const calls: number[] = [];
function* transcribe(clips: number[]): Generator<string> {
  for (const c of clips) {
    calls.push(c); // 이 줄은 꺼낼 때에만 실행됨
    yield `구간 ${c} 받아쓰기`;
  }
}
const segments = transcribe([1, 2, 3]);
const before = calls.length;
const segs = Array.from(segments);
console.log(`호출 직후 처리한 구간 ${before}개 -> 꺼낸 뒤 ${calls.length}개 | ${segs.join(" / ")}`);
check(before === 0 && Array.isArray(segs) && calls.length === 3, "제너레이터는 꺼낼 때 실제로 일해요.");

quant.typescript:
// D8 · Part 3 · 양자화: 숫자를 작게 저장하기 (int8 눈금 · 오차 · 모델 크기) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_quant.ts
//   가중치 하나를 scale = 최대값/127 눈금으로 int8 에 담고 되돌려 오차를 재고, 한 덩어리 vs 행마다 눈금, 숫자 형식별 모델 크기(float32 · float16 · int8)를 계산
// 대체 경로: whisper-small 의 실제 가중치 대신, 정규분포 난수 가중치(256 x 192)를 쓴다.
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 21;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

const ROWS = 256;
const COLS = 192;
const w = Float32Array.from({ length: ROWS * COLS }, () => 0.04 * randn());
w[5 * COLS + 5] = 1.2; // 튀는 값 하나: 눈금 간격을 키워 나머지 오차를 키운다
const absMax = (arr: Float32Array | number[]): number => arr.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
const clamp127 = (v: number): number => Math.max(-127, Math.min(127, Math.round(v)));

const scale = absMax(w) / 127; // 눈금 간격 (한 덩어리 전체에 하나)
const q = Int8Array.from(w, (v) => clamp127(v / scale)); // int8 정수로
let errSum = 0;
let errMax = 0;
let mag = 0;
w.forEach((v, i) => {
  const e = Math.abs(v - q[i] * scale); // 되돌리기
  errSum += e;
  errMax = Math.max(errMax, e);
  mag += Math.abs(v);
});
console.log(`가중치 모양 (${ROWS}, ${COLS}), 개수 ${w.length} | 눈금 간격 scale = ${scale.toFixed(6)}`);
console.log(`원래  : ${Array.from(w.slice(0, 5), (v) => v.toFixed(5)).join(" ")}`);
console.log(`정수 q: ${Array.from(q.slice(0, 5)).join(" ")}`);
console.log(`평균 오차 ${(errSum / w.length).toExponential(2)} (가중치 평균 크기의 ${((errSum / mag) * 100).toFixed(1)}%)`);
console.log(`메모리: float32 ${w.byteLength / 1000} KB -> int8 ${q.byteLength / 1000} KB`);
check(w.byteLength === 4 * q.byteLength && errMax <= scale / 2 + 1e-6, "int8 은 1/4 크기이고, 오차는 눈금 간격의 절반 이하예요.");

// 행마다 눈금: 튀는 값이 있어도 다른 행의 오차는 작다
let err2 = 0;
for (let r = 0; r < ROWS; r++) {
  const row = w.subarray(r * COLS, (r + 1) * COLS);
  const rs = absMax(row) / 127;
  row.forEach((v) => {
    err2 += Math.abs(v - clamp127(v / rs) * rs);
  });
}
console.log(`눈금 하나 ${(errSum / w.length).toExponential(2)} vs 행마다 눈금 ${(err2 / w.length).toExponential(2)}`);
check(err2 < errSum, "행마다 눈금을 쓰면 평균 오차가 줄어요.");

// 숫자 형식별 모델 크기
const BYTES: Record<string, number> = { float32: 4, float16: 2, int8: 1 };
const nParams = 244_000_000; // whisper-small 약 2억 4천만 개
for (const [k, b] of Object.entries(BYTES)) console.log(`  ${k.padEnd(8)}: 숫자 하나 ${b}바이트 -> 가중치 약 ${String(Math.round((nParams * b) / 1e6)).padStart(5)} MB`);
check(BYTES.int8 * 8 === 8 && BYTES.float32 / BYTES.int8 === 4, "int8 = 8비트 = 1바이트.");

batch.typescript:
// D8 · Part 4 · VAD 와 배치: 듣지 않아도 될 것은 빼고, 한 번에 여러 개 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_batch.ts
//   에너지 VAD 로 말 구간만 잘라 내고, 구간들을 쌓아(배치) 한 번에 처리해도 결과가 같다는 것과 호출 횟수가 줄어드는 것을 확인
// 대체 경로: faster-whisper 의 vad_filter · BatchedInferencePipeline(silero-vad, 모델 다운로드 필요) 대신 프레임 에너지 VAD 와 장난감 행렬곱을 쓴다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 8;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

// 합성 녹음: 말 4구간 + 사이는 거의 무음
const spans: [number, number][] = [[1.0, 2.4], [3.5, 4.6], [7.0, 8.5], [9.5, 10.3]];
const y = Float32Array.from({ length: 12 * SR }, (_, i) => {
  const t = i / SR;
  const on = spans.some(([a, b]) => t >= a && t < b);
  return (on ? 0.3 * Math.sin(2 * Math.PI * 190 * t) : 0) + 0.001 * randn();
});

function vad(sig: Float32Array, frame: number = 400, thr: number = 0.02, minGapFrames: number = 25): [number, number][] {
  const n = Math.floor(sig.length / frame);
  const on: boolean[] = [];
  for (let i = 0; i < n; i++) {
    let s = 0;
    for (let j = 0; j < frame; j++) s += sig[i * frame + j] ** 2;
    on.push(Math.sqrt(s / frame) > thr);
  }
  const segs: [number, number][] = [];
  let start = -1;
  let gap = 0;
  on.forEach((v, i) => {
    if (v) {
      if (start < 0) start = i;
      gap = 0;
    } else if (start >= 0) {
      gap++;
      if (gap >= minGapFrames) {
        // 0.625초 이상 쉬면 구간 끝
        segs.push([(start * frame) / SR, ((i - gap + 1) * frame) / SR]);
        start = -1;
        gap = 0;
      }
    }
  });
  if (start >= 0) segs.push([(start * frame) / SR, (n * frame) / SR]);
  return segs;
}

const found = vad(y);
const speechSec = found.reduce((s, [a, b]) => s + (b - a), 0);
console.log("VAD 구간:", found.map(([a, b]) => `(${a.toFixed(2)}, ${b.toFixed(2)})`).join(" "));
console.log(`Whisper 에 넣는 길이 ${speechSec.toFixed(1)}초 / 전체 ${y.length / SR}초 (${Math.round((speechSec / (y.length / SR)) * 100)}%)`);
check(found.length === 4 && found.every(([a, b], i) => Math.abs(a - spans[i][0]) < 0.1 && Math.abs(b - spans[i][1]) < 0.1), "VAD 가 말 구간 4개를 찾아야 해요.");

// 배치: 구간마다 따로 곱하기(4번 호출) vs 길이를 맞춰 쌓아 한 번에 곱하기(1번 호출)
const D = 16;
const W = Array.from({ length: D }, () => Array.from({ length: D }, () => 0.1 * randn()));
const feats = found.map(() => Array.from({ length: 20 }, () => Array.from({ length: D }, randn))); // 구간마다 특징 20칸
let calls = 0;
const matmul = (X: number[][]): number[][] => {
  calls++; // 호출 1번
  return X.map((row) => W[0].map((_, j) => row.reduce((s, v, i) => s + v * W[i][j], 0)));
};
const oneByOne = feats.map((f) => matmul(f)); // 호출 4번
const callsSeq = calls;
const BATCH = feats.length; // 묶음 크기: 한 번에 몇 구간
calls = 0;
const stacked = matmul(feats.flat()); // 호출 1번: 모든 구간의 칸을 위아래로 쌓아 곱함
const batched = Array.from({ length: BATCH }, (_, k) => stacked.slice(k * 20, (k + 1) * 20));
const diff = Math.max(...oneByOne.flatMap((m, k) => m.flatMap((row, r) => row.map((v, c) => Math.abs(v - batched[k][r][c])))));
console.log(`호출 횟수: 차례로 ${callsSeq}번 -> 배치 ${calls}번 | 결과 차이 ${diff.toExponential(1)}`);
check(BATCH === 4 && calls === 1 && diff < 1e-12, "배치로 곱해도 결과는 같아야 해요.");

wcpp.typescript:
// D8 · Part 5 · whisper.cpp: 블록 양자화 q5_0 (ggml) 직접 구현 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_wcpp.ts
//   ggml 의 q5_0 방식: 가중치 32개를 한 블록으로 묶어 블록마다 눈금(float16) 하나 + 5비트 정수 32개로 저장. 크기(5.5비트/값)와 복원 오차를 float16 과 비교
// 대체 경로: whisper.cpp 를 빌드해 ggml-small.bin 을 양자화하는 대신, 같은 블록 규칙을 구현해 난수 가중치에 적용한다. (cmake · git · 모델 다운로드 불필요) float16 눈금은 float32 로 둔다.
const BLOCK = 32;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 4;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

function quantizeQ50(w: Float32Array): { d: Float32Array; q: Uint8Array } {
  const nb = w.length / BLOCK;
  const d = new Float32Array(nb);
  const q = new Uint8Array(w.length);
  for (let b = 0; b < nb; b++) {
    let amax = 0; // 부호 있는 최대 절대값
    for (let i = 0; i < BLOCK; i++) if (Math.abs(w[b * BLOCK + i]) > Math.abs(amax)) amax = w[b * BLOCK + i];
    d[b] = amax / -16; // 블록 눈금
    const inv = d[b] === 0 ? 0 : 1 / d[b];
    for (let i = 0; i < BLOCK; i++) q[b * BLOCK + i] = Math.max(0, Math.min(31, Math.floor(w[b * BLOCK + i] * inv + 16.5))); // 0..31 (5비트)
  }
  return { d, q };
}
const dequantizeQ50 = (d: Float32Array, q: Uint8Array): Float32Array => Float32Array.from(q, (v, i) => (v - 16) * d[Math.floor(i / BLOCK)]);

const w = Float32Array.from({ length: BLOCK * 1024 }, () => 0.05 * randn()); // 가중치 약 3만 개
const { d, q } = quantizeQ50(w);
const wHat = dequantizeQ50(d, q);

const bitsPerWeight = (BLOCK * 5 + 16) / BLOCK; // 5비트 x 32 + float16 눈금 1개
const sizeF16 = w.length * 2;
const sizeQ5 = (w.length * bitsPerWeight) / 8;
let errSum = 0;
let mag = 0;
let errMax = 0;
w.forEach((v, i) => {
  const e = Math.abs(v - wHat[i]);
  errSum += e;
  mag += Math.abs(v);
  errMax = Math.max(errMax, e);
});
const mae = errSum / mag;
console.log(`q5_0: 값 하나당 ${bitsPerWeight.toFixed(1)}비트 | float16 ${(sizeF16 / 1e3).toFixed(0)} KB -> q5_0 ${(sizeQ5 / 1e3).toFixed(0)} KB (${Math.round((sizeQ5 / sizeF16) * 100)}%)`);
console.log(`원래  : ${Array.from(w.slice(0, 4), (v) => v.toFixed(4)).join(" ")}\n복원  : ${Array.from(wHat.slice(0, 4), (v) => v.toFixed(4)).join(" ")}\n평균 상대 오차 ${(mae * 100).toFixed(1)}%, 최대 오차 ${errMax.toFixed(4)}`);
check(Math.max(...q) <= 31 && sizeQ5 < 0.5 * sizeF16, "5비트 정수(0~31)로 담으면 float16 의 절반보다 작아요.");
check(mae < 0.06, "q5_0 평균 상대 오차는 몇 % 이내예요.");

const QTYPE = "q5_0"; // 5비트 형식 이름 (빈칸의 답)
console.log("양자화 형식 이름:", QTYPE);
check(QTYPE === "q5_0" && BLOCK === 32, "ggml 5비트 형식 이름은 q5_0, 블록은 32개예요.");

chunk.typescript:
// D8 · Part 6 · 고정 청크 vs 끝점(VAD) 청크: 단어가 잘리는지 비교 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_chunk.ts
//   스트리밍에서 오디오를 3초씩 자르면 단어 중간이 잘려 인식이 깨진다. 단어가 있는 합성 신호에서 고정 3초 청크와 '말 사이 쉼' 에서 자르는 청크가 단어를 몇 개 자르는지 센다
// 대체 경로: Whisper 로 받아쓰기하는 대신, 단어 구간(시작·끝)이 알려진 합성 신호로 '잘린 단어 수' 를 센다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

// 단어 구간(초): (단어, 시작, 끝). 사이에 짧은 쉼이 있다
const WORDS: [string, number, number][] = [
  ["안녕하세요", 0.2, 1.1], ["오늘은", 1.3, 2.0], ["위스퍼를", 2.3, 3.4], ["빠르게", 3.6, 4.3], ["만드는", 4.5, 5.2], ["방법을", 5.9, 6.7], ["배웁니다", 6.9, 8.0],
];
const total = 8.4;
const y = Float32Array.from({ length: Math.floor(total * SR) }, (_, i) => {
  const t = i / SR;
  return WORDS.some(([, a, b]) => t >= a && t < b) ? 0.3 * Math.sin(2 * Math.PI * 200 * t) : 0;
});

// 고정 청크: 3초 간격 (빈칸: 간격도 CHUNK_N)
const CHUNK_SEC = 3.0;
const CHUNK_N = Math.floor(CHUNK_SEC * SR);
const chunks: [number, number][] = [];
for (let i = 0; i < y.length; i += CHUNK_N) chunks.push([i / SR, Math.min(i + CHUNK_N, y.length) / SR]);
const cutFixed = WORDS.filter(([, a, b]) => chunks.slice(1).some(([c0]) => a < c0 && c0 < b)).map((w) => w[0]); // 청크 경계가 단어 한가운데 걸린 단어
console.log(`고정 3초 청크 ${chunks.length}개, 경계 [${chunks.slice(1).map((c) => c[0]).join(", ")}] -> 잘린 단어 [${cutFixed.join(", ")}]`);
check(Math.abs(chunks.reduce((s, c) => s + c[1] - c[0], 0) - total) < 1e-9 && chunks.length === Math.ceil(y.length / CHUNK_N), "청크끼리 겹치지 않으려면 간격도 CHUNK_N 이어야 해요.");

// 끝점 청크: 3초가 넘으면 그 뒤 첫 번째 쉼(에너지가 낮은 프레임)에서 자른다
const frame = 160;
const bounds: number[] = [];
let last = 0;
for (let i = 0; i < Math.floor(y.length / frame); i++) {
  let s = 0;
  for (let j = 0; j < frame; j++) s += y[i * frame + j] ** 2;
  const now = (i * frame) / SR;
  if (Math.sqrt(s / frame) < 0.02 && now - last >= CHUNK_SEC) {
    bounds.push(now);
    last = now;
  }
}
const cutEnd = WORDS.filter(([, a, b]) => bounds.some((c0) => a < c0 && c0 < b)).map((w) => w[0]);
console.log(`끝점 청크 경계 [${bounds.map((b) => b.toFixed(2)).join(", ")}] -> 잘린 단어 [${cutEnd.join(", ")}]`);
check(cutFixed.length >= 1 && cutEnd.length === 0, "쉼에서 자르면 단어가 잘리지 않아요.");

agree.typescript:
// D8 · Part 6 · LocalAgreement: 두 번 같은 말이 나오면 확정 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_agree.ts
//   1초마다 늘어나는 소리를 받아쓴 가설(끝부분이 자주 바뀜)에서, 이번 가설과 지난 가설의 공통 앞부분(lcp)만 확정하는 LocalAgreement-2 스트리밍
// 대체 경로: faster-whisper 로 1초씩 받아쓰는 대신, 시각마다 나올 법한 가설(끝부분이 흔들리는 문장)을 손으로 적어 둔 장난감 스트림을 쓴다.
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function lcp(a: string[], b: string[]): number {
  // longest common prefix: 앞에서부터 같은 단어가 몇 개 이어지나
  let i = 0;
  while (i < Math.min(a.length, b.length) && a[i] === b[i]) i++;
  return i;
}

const tests: [string[], string[], number][] = [
  [["아이구루", "교육"], ["아이구루", "교육센터에서", "라이"], 1],
  [["아이구루", "교육센터에서", "라이"], ["아이구루", "교육센터에서", "라이브킷과", "파이"], 2],
  [["가", "나"], ["다", "나"], 0],
  [[], ["가"], 0],
];
for (const [a, b, want] of tests) console.log(`[${a.join(",")}] vs [${b.join(",")}] -> ${lcp(a, b)} ${lcp(a, b) === want ? "맞음" : "틀림"}`);
check(tests.every(([a, b, want]) => lcp(a, b) === want), "같은 위치 i 의 b 단어와 비교합니다: b[i]");

// 스트림: (시각 초, 그 시점까지 들은 소리의 가설). 끝 단어는 불안정해서 바뀐다
const STREAM: [number, string[]][] = [
  [1, ["아이구루"]],
  [2, ["아이구루", "교육"]],
  [3, ["아이구루", "교육센터에서", "라이"]],
  [4, ["아이구루", "교육센터에서", "라이브킷과", "파이"]],
  [5, ["아이구루", "교육센터에서", "라이브킷과", "파이프캣으로", "음성"]],
  [6, ["아이구루", "교육센터에서", "라이브킷과", "파이프캣으로", "음성", "에이전트를"]],
  [7, ["아이구루", "교육센터에서", "라이브킷과", "파이프캣으로", "음성", "에이전트를", "만듭니다"]],
];
const committed: [string, number][] = []; // (확정 단어, 확정된 시각)
let prev: string[] = [];
for (const [now, hyp] of STREAM) {
  const pending = hyp.slice(committed.length); // 아직 확정 안 된 부분만 비교
  const n = lcp(prev, pending);
  for (const w of pending.slice(0, n)) committed.push([w, now]);
  prev = pending.slice(n);
  console.log(`${now}초 | 가설 끝 "${hyp[hyp.length - 1]}" | 새로 확정 [${pending.slice(0, n).join(", ")}] | 확정 누적 ${committed.length}개`);
}

// 마지막에 소리가 끝나면 남은 가설을 모두 확정
const finalHyp = STREAM[STREAM.length - 1][1];
for (const w of finalHyp.slice(committed.length)) committed.push([w, STREAM[STREAM.length - 1][0] + 1]);
check(committed.map((c) => c[0]).join(" ") === finalHyp.join(" "), "확정한 단어를 이어 붙이면 마지막 가설과 같아야 해요.");
const delay = committed.map(([, t], i) => t - (i + 1)); // 단어가 처음 가설에 나온 시각 대비 확정 지연
console.log("확정 지연(초):", delay.join(", "));
check(Math.max(...delay) <= 2, "두 번 확인하므로 지연은 보통 1~2초 안이에요.");

latency.typescript:
// D8 · Part 6 · 지연 비교: 통째로 vs 고정 청크 vs LocalAgreement — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d08_latency.ts
//   단어가 끝난 시각부터 화면에 보이기까지의 지연(평균·최대)을 세 방식으로 계산하고, 1초 단위 계산이 1초 안에 끝나야 '실시간' 이라는 조건을 확인
// 대체 경로: faster-whisper 로 재는 대신, 단어 끝 시각표와 계산 시간(가정값)으로 지연을 계산하는 시뮬레이션이다.
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
const median = (a: number[]): number => [...a].sort((x, y) => x - y)[Math.floor(a.length / 2)];

const wordEnd = [1.1, 2.0, 3.4, 4.3, 5.2, 6.7, 8.0, 9.2, 10.4, 11.5]; // 단어가 끝나는 시각(초)
const TOTAL = 12.0; // 녹음이 끝나는 시각
const COMPUTE = 0.4; // 한 번 받아쓰는 데 걸리는 시간 (가정)

// 1) 통째로: 녹음이 끝난 뒤 한 번에 -> 모든 단어가 TOTAL + COMPUTE 에 보임
const latFull = wordEnd.map((e) => TOTAL + COMPUTE - e);

// 2) 고정 3초 청크: 단어가 들어 있는 청크가 끝난 뒤(청크 끝 + 계산)에 보임
const CHUNK = 3.0;
const latChunk = wordEnd.map((e) => Math.min(Math.ceil(e / CHUNK) * CHUNK, TOTAL) + COMPUTE - e);

// 3) LocalAgreement: 1초마다 받아쓰고, 단어는 '두 번 연속 같을 때' 확정 -> 단어 끝 다음 1초 눈금 + 1초(재확인) + 계산
const STEP = 1.0;
const latAgree = wordEnd.map((e) => Math.min(Math.ceil(e / STEP) * STEP + STEP, TOTAL + STEP) + COMPUTE - e);

for (const [name, lat] of [["통째로", latFull], ["고정 3초 청크", latChunk], ["LocalAgreement", latAgree]] as [string, number[]][]) {
  console.log(`${name.padEnd(14)} | 지연 평균 ${mean(lat).toFixed(2)}초, 중앙값 ${median(lat).toFixed(2)}초, 최대 ${Math.max(...lat).toFixed(2)}초`);
}
check(mean(latAgree) < mean(latChunk) && mean(latChunk) < mean(latFull), "지연은 LocalAgreement < 고정 청크 < 통째로 순이에요.");

// 실시간 조건: 1초 분량을 받아쓰는 데 1초가 안 걸려야 한다 (계산 시간이 쌓이지 않음)
const comp = [0.3, 0.35, 0.4, 0.45, 0.42, 0.38];
const realtime = Math.max(...comp) < STEP;
console.log(`1초마다 계산 시간: 평균 ${mean(comp).toFixed(2)}초, 최대 ${Math.max(...comp).toFixed(2)}초 -> ${realtime ? "실시간 가능" : "1초 초과: 더 작은 모델 · int8 · GPU 필요"}`);
check(realtime && !(Math.max(0.5, 1.2) < STEP), "계산이 1초 안에 끝나야 실시간이에요.");
